def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Find the vertical divider.
    divider_col = next(
        c for c in range(w)
        if all(grid[r][c] == 2 for r in range(h))
    )

    background = max(
        set(v for row in grid for v in row if v != 2),
        key=lambda v: sum(row.count(v) for row in grid)
    )
    points = [
        (r, c)
        for r in range(h) for c in range(w)
        if grid[r][c] not in (background, 2)
    ]
    leftmost = min(c for r, c in points)
    rightmost = max(c for r, c in points)

    target_col = rightmost + 1 if divider_col < leftmost else leftmost - 1
    for r in range(h):
        out[r][target_col] = 8
    return out
